"use client";

import { useEffect, useRef, useState, useSyncExternalStore } from "react";
import Link from "next/link";
import "./learning-lab.css";

const configuredOrigin = process.env.NEXT_PUBLIC_THESIS_ROADMAP_ORIGIN || "http://127.0.0.1:4387";
const roadmapOrigin = /^http:\/\/127\.0\.0\.1:\d{2,5}$/.test(configuredOrigin) ? configuredOrigin : "http://127.0.0.1:4387";
type Progress = { completed: number; total: number; connected: boolean };
const subscribeToLocation = () => () => {};
const localLocation = () => ["127.0.0.1", "localhost"].includes(window.location.hostname);

export default function LearningLabPage() {
  const frame = useRef<HTMLIFrameElement>(null);
  const local = useSyncExternalStore(subscribeToLocation, localLocation, () => false);
  const [progress, setProgress] = useState<Progress | null>(null);
  const [waiting, setWaiting] = useState(true);

  useEffect(() => {
    let lastMessage = Date.now();
    const receive = (event: MessageEvent) => {
      if (event.origin !== roadmapOrigin || event.source !== frame.current?.contentWindow) return;
      const data = event.data;
      if (!data || data.type !== "thesis-roadmap-progress" || data.roadmapId !== "thesis-predefense-2026" || data.completionBasis !== "practice") return;
      if (!Number.isInteger(data.total) || data.total < 1 || !Number.isInteger(data.completed) || data.completed < 0 || data.completed > data.total || typeof data.connected !== "boolean") return;
      lastMessage = Date.now();
      setWaiting(false);
      setProgress({ completed: data.completed, total: data.total, connected: data.connected });
    };
    window.addEventListener("message", receive);
    const timeout = window.setInterval(() => {
      if (Date.now() - lastMessage > 9000) {
        setWaiting(false);
        setProgress(previous => previous ? { ...previous, connected: false } : null);
      }
    }, 3000);
    return () => { window.removeEventListener("message", receive); window.clearInterval(timeout); };
  }, []);

  const connected = progress?.connected === true;
  const roadmapUrl = local && /^#D\d{2}$/.test(window.location.hash) ? roadmapOrigin + window.location.hash : roadmapOrigin;
  return (
    <main className="learning-lab-shell">
      <header className="learning-lab-header">
        <div>
          <p className="learning-lab-kicker">STUDY TRACKER · LEARNING LAB</p>
          <h1>Lernlabor: 26 Tage, ein gemeinsamer Fortschritt</h1>
          <p>Eine abgeschlossene Übung mit deinem Arbeitsnachweis wird grün. Eine Erklärung allein zählt noch nicht als erledigte Übung.</p>
          <p>Deutsch ist die Unterrichtssprache. Pro aktivem Lerntag sind 30 Minuten für Hören, Sprechen und Schreiben innerhalb der bestehenden Lernzeit vorgesehen.</p>
        </div>
        <div className={`learning-lab-progress ${connected ? "is-connected" : ""}`} aria-live="polite">
          <strong>{progress ? `${progress.completed} / ${progress.total}` : "—"}</strong>
          <span>Übungen abgeschlossen</span>
          <small>{waiting ? "Verbindung wird geprüft …" : connected ? "Gemeinsamer Fortschritt verbunden" : "Verbindung unterbrochen"}</small>
          {progress && <progress aria-label="Abgeschlossene Übungen" value={progress.completed} max={progress.total} />}
        </div>
      </header>
      {!waiting && !connected && <aside className="learning-lab-notice" role="status">
        {local ? <>Öffne <b>OPEN-STUDY-WORKSPACE.cmd</b> im gemeinsamen Projektordner. Der Lernserver muss laufen. <button type="button" onClick={() => { setWaiting(true); if (frame.current) frame.current.src = roadmapOrigin; }}>Erneut verbinden</button></> : "Dieser gemeinsame Lernspeicher läuft auf deinem Windows-Rechner. Eine Online-Verbindung ist noch nicht eingerichtet."}
      </aside>}
      <div className="learning-lab-actions">
        <Link href="/career">Sechsmonatsplan mit Deutschtraining</Link>
        <Link href="/">Zum bisherigen Studienplan</Link>
        {local && <a href={roadmapOrigin} target="_blank" rel="noreferrer">Roadmap in eigenem Fenster öffnen</a>}
      </div>
      {local && <iframe ref={frame} src={roadmapUrl} title="Deutsche Lernroadmap mit 26 Tagen und gemeinsamem Übungsfortschritt" className="learning-lab-frame" referrerPolicy="origin" />}
      <p className="learning-lab-footnote">Der 26-Tage-Lernpfad ergänzt den bisherigen Studienplan. Die separate Bewertung deiner Kenntnisse bleibt erhalten.</p>
    </main>
  );
}
